{
  "judgments": [
    {
      "proposal_id": "P0000",
      "quotes": [
        "c. The court order or decree must be final:",
        "An applicant with a pending name change must not be issued a passport in her/his new name."
      ],
      "rationale": "C0011 omitted the governing lead-in prerequisite from subsection c requiring court orders or decrees to be final, rendering the prohibition overbroad. The proposed scope correction incorporates this context from the source and resolves the defect identified in the audit.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "quotes": [
        "c. The court order or decree must be final:",
        "An applicant with a pending name change must not be issued a form FS-240 in her/his new name."
      ],
      "rationale": "C0012 omitted the governing lead-in condition from subsection c establishing that the restriction applies under court orders or decrees requiring finality. The proposal correctly remedies this scope omission.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "quotes": [
        "c. The court order or decree must be final:",
        "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time."
      ],
      "rationale": "Baseline claim C0013 left scope entirely blank, omitting the governing court order context and the explicit timing conditions. The proposed edit incorporates these conditions into scope, fixing the defect flagged during audit.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0003",
      "quotes": [
        "The court order or decree must list both the applicant's current and former name(s)."
      ],
      "rationale": "Baseline claim C0014 faithfully conveys the full meaning of the source without assigning an actor to an inanimate court order or decree. Components can remain unstructured when the meaning is complete, and inventing an actor for an inanimate document does not fix a real defect.",
      "verdict": "unsupported"
    },
    {
      "proposal_id": "P0004",
      "quotes": [
        "Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."
      ],
      "rationale": "The audit flagged unit 7b00222121ed9e345d42c8abbdab470426ad5afd5333b84bc4ad0b51e332e813 as missing. The proposal faithfully adds this omitted statement with exact source support.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0005",
      "quotes": [
        "Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English."
      ],
      "rationale": "Audit unit 63105060fa27496ef9d8dd245720aaed27c4255e72283b8ea4c35376217645f5 was missing from the claim set. The proposal recovers this observation faithfully from the text.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0006",
      "quotes": [
        "If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles."
      ],
      "rationale": "Audit unit d1c27aa81ef32124de25841201cb47a48fa65ee39d895243b1a2c1f0d24ad194 was missing. The proposal adds the mandatory instruction to follow ranks and titles guidance when 'Sr.' represents 'Señor', fully supported by the source.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0007",
      "quotes": [
        "Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."
      ],
      "rationale": "Audit unit 00366369c0631fb379f8e9ce6c07dfe7df2320bf5f13903e43fbff9903f5af7f was missing from the claim set. The proposal recovers this provision accurately from the text.",
      "verdict": "supported"
    }
  ]
}
